import{a as n}from"./chunk-II2P5MV5.mjs";import{a as m,b as g,e as v}from"./chunk-EFWS3KQR.mjs";import{i as d,j as p}from"./chunk-Q45PAZO5.mjs";import{G as u,L as s,V as c,s as l}from"./chunk-BVKZKKS2.mjs";var f=class o{document=s(c);router=s(v);route=s(g);meta=s(d);titleService=s(p);baseUrl=n.siteUrl;defaultTitle=n.defaultTitle;defaultDescription=n.defaultDescription;defaultImage=n.defaultOgImage;initCanonicalUrlListener(){this.handleRouteChange(this.router.url),this.router.events.pipe(l(e=>e instanceof m)).subscribe(e=>{this.handleRouteChange(e.urlAfterRedirects||e.url)})}handleRouteChange(e){this.updateCanonicalUrl(e);let t=this.route.root;for(;t.firstChild;)t=t.firstChild;let i=t.snapshot.data;if(i){let a=i.description||this.defaultDescription,r=i.ogImage||i.image||this.defaultImage;this.updateMeta({title:t.snapshot.title||this.defaultTitle,description:a,image:r})}}updateCanonicalUrl(e){if(!e)return;let t=e.split("?")[0].split("#")[0],i=`${this.baseUrl}${t==="/"?"":t}`,a=this.document.querySelector("link[rel='canonical']");a||(a=this.document.createElement("link"),a.setAttribute("rel","canonical"),this.document.head.appendChild(a)),a.setAttribute("href",i),this.meta.updateTag({property:"og:url",content:i}),this.meta.updateTag({name:"twitter:url",content:i})}updateMeta(e){let t=e.title||this.defaultTitle,i=e.description||this.defaultDescription,a=e.image||this.defaultImage;if(this.titleService.setTitle(t),this.meta.updateTag({name:"description",content:i}),e.keywords){let r=Array.isArray(e.keywords)?e.keywords.join(", "):e.keywords;this.meta.updateTag({name:"keywords",content:r})}this.meta.updateTag({property:"og:title",content:t}),this.meta.updateTag({property:"og:description",content:i}),this.meta.updateTag({property:"og:image",content:a}),this.meta.updateTag({name:"twitter:title",content:t}),this.meta.updateTag({name:"twitter:description",content:i}),this.meta.updateTag({name:"twitter:image",content:a})}resetMeta(){this.updateMeta({title:this.defaultTitle,description:this.defaultDescription,image:this.defaultImage})}static \u0275fac=function(t){return new(t||o)};static \u0275prov=u({token:o,factory:o.\u0275fac,providedIn:"root"})};var P=[{id:3,order:1,slug:"liko-auto",title:"Marketplace automobile connect\xE9e & services auto au Cameroun",clientName:"Liko Auto",showcaseImage:"/images/projects/liko-auto/liko-auto.webp",isSpotlighted:!0,keyResults:[{value:"200+",label:"ventes vis\xE9es / mois"},{icon:"faComments",label:"Messagerie instantan\xE9e"},{icon:"faShieldAlt",label:"Transactions s\xE9curis\xE9es"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Contexte & Ambition"},{id:"challenges",label:"Les Enjeux"},{id:"approach",label:"Notre Approche"},{id:"solution",label:"La Solution"},{id:"process",label:"Le Processus"},{id:"retrospective",label:"R\xE9trospective & Bilan"},{id:"conclusion",label:"Conclusion"},{id:"gallery",label:"Galerie & Visuels"}],blocks:[{type:"overview",data:{title:'Plateforme automobile connect\xE9e & <span class="highlight">marketplace de confiance</span> au Cameroun',impactStatement:"Conception et d\xE9veloppement d'une solution compl\xE8te (application mobile pour acheteurs et vendeurs, vitrine web publique et espace de gestion administrateur) permettant de digitaliser et s\xE9curiser le march\xE9 de l'automobile d'occasion et des pi\xE8ces d\xE9tach\xE9es."}},{type:"media",data:{images:[{src:"/images/projects/liko-auto/mobile-liko-auto.webp",alt:"Liko Auto Application Mobile",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Contexte & Ambition du Projet",paragraphs:["Le march\xE9 de l\u2019automobile d\u2019occasion au Cameroun repr\xE9sentait un volume annuel estim\xE9 en <strong>2026</strong> entre <strong>10 000 et 12 500 v\xE9hicules vendus</strong> (donn\xE9es estim\xE9es d'apr\xE8s les rapports de transit douanier et d'immatriculation 2026), dont pr\xE8s de 25 % financ\xE9s directement par la diaspora.","Jusqu'alors frein\xE9 par l'absence de r\xE9seau structur\xE9, les risques d'escroquerie et le manque de transparence, ce secteur pr\xE9sentait une opportunit\xE9 majeure. <strong>Liko Auto</strong> est n\xE9 avec la vision de b\xE2tir un \xE9cosyst\xE8me de confiance unifiant acheteurs, vendeurs, garages agr\xE9\xE9s et \xE9quipementiers.","L'ambition strat\xE9gique du projet est de s'imposer d'abord comme la r\xE9f\xE9rence au Cameroun, puis de <strong>se d\xE9ployer progressivement dans l'ensemble de la sous-r\xE9gion Afrique Centrale (CEMAC)</strong>. Pour soutenir ce projet d'envergure internationale, l'\xE9quipe d'Evolia Tech a con\xE7u et r\xE9alis\xE9 une plateforme sur-mesure, scalable et pr\xEAte \xE0 accompagner cette expansion multi-pays."]}},{type:"challenges",data:{id:"challenges",title:"Les Vrais Enjeux du Projet",challenges:["Concevoir une exp\xE9rience utilisateur fluide, rapide et ergonomique sur smartphones et tablettes (pour les acheteurs en d\xE9placement) et sur ordinateur (pour la gestion administrative).","Accompagner et simplifier les d\xE9marches administratives complexes (immatriculation, mutation de carte grise, v\xE9rifications d\u2019authenticit\xE9 des pi\xE8ces douani\xE8res).","S\xE9curiser la mise en relation gr\xE2ce \xE0 une messagerie instantan\xE9e int\xE9gr\xE9e qui prot\xE8ge la confidentialit\xE9 des donn\xE9es personnelles.","Encourager la d\xE9claration spontan\xE9e des ventes r\xE9ussies pour fluidifier le mod\xE8le \xE9conomique par commission.","Digitaliser et certifier la vente et la livraison de pi\xE8ces d\xE9tach\xE9es automobiles d\u2019origine.","Structurer un r\xE9seau de garages partenaires agr\xE9\xE9s pour l\u2019inspection technique et l\u2019entretien des v\xE9hicules."]}},{type:"text",data:{id:"approach",title:"Notre Approche & M\xE9thodologie",paragraphs:["Pour transformer cette vision en une plateforme performante, <strong>Evolia Tech a con\xE7u une architecture sur-mesure et \xE9volutive</strong>. L'objectif : offrir une navigation fluide et instantan\xE9e sur mobile (m\xEAme en zone \xE0 faible couverture r\xE9seau) et permettre d\u2019ajouter facilement de nouvelles fonctionnalit\xE9s au fil de la croissance, sans jamais devoir repartir de z\xE9ro.","Au-del\xE0 de l'interface publique, nous avons d\xE9velopp\xE9 un <strong>espace d'administration complet et s\xE9curis\xE9</strong>. Chaque membre de l'\xE9quipe Liko Auto (mod\xE9rateurs d'annonces, gestionnaires de stock de pi\xE8ces, suiveurs de transactions) dispose d'un acc\xE8s adapt\xE9 \xE0 son r\xF4le pour piloter l'activit\xE9 au quotidien en toute autonomie."]}},{type:"media",data:{images:[{src:"/images/projects/liko-auto/dahsboard-admin-liko-auto.webp",alt:"Espace Administration & Dashboard Liko Auto"}]}},{type:"solution",data:{id:"solution",title:"La Solution 360\xB0 Liko Auto",introText:"Pour concr\xE9tiser les ambitions de Liko Auto, l\u2019\xE9quipe d\u2019Evolia Tech a con\xE7u et d\xE9ploy\xE9 un \xE9cosyst\xE8me digital complet 360\xB0, interconnectant une application mobile grand public, un portail web \xE0 fort trafic et un outil de pilotage m\xE9tier sur-mesure.",solutions:[{title:"1. Application Mobile (iOS & Android)",subtitle:"Pour les acheteurs & vendeurs",features:["D\xE9veloppement d\u2019une interface fluide de recherche et d\u2019achat de v\xE9hicules certifi\xE9s","Int\xE9gration d\u2019une boutique mobile pour la commande directe de pi\xE8ces d\xE9tach\xE9es et \xE9quipements d\u2019origine","Module d\u2019assistance guid\xE9e pour la simplification des d\xE9marches administratives (carte grise, mutation et douane)","Int\xE9gration d\u2019une messagerie instantan\xE9e s\xE9curis\xE9e et prise de rendez-vous directe en garages agr\xE9\xE9s"],techStack:["Flutter","iOS & Android","Firebase Push","WebSockets"]},{title:"2. Portail Web & Vitrine M\xE9dia SEO",subtitle:"Pour la visibilit\xE9 & le SEO Google",features:["Conception d\u2019une architecture web Angular SSR \xE0 chargement instantan\xE9 pour capter le trafic de recherche Google","D\xE9veloppement du portail m\xE9dia int\xE9grant articles conseils, guides d\u2019achat et actualit\xE9s du secteur automobile","Mise en place de la plateforme web e-commerce pour le catalogue et la commande de pi\xE8ces automobiles"],techStack:["Angular SSR","TypeScript","SEO Google","SCSS"]},{title:"3. Espace d\u2019Administration Sur-Mesure",subtitle:"Pour le contr\xF4le op\xE9rationnel Liko Auto",features:["Cr\xE9ation d\u2019un dashboard administrateur centralis\xE9 pour la mod\xE9ration et la validation des annonces en temps r\xE9el","Configuration d\u2019un syst\xE8me d\u2019habilitations strictes (RBAC) adapt\xE9 aux diff\xE9rents profils d\u2019op\xE9rateurs Liko Auto","Impl\xE9mentation d\u2019outils automatis\xE9s de suivi des commissions, de gestion de stock et de facturation"],techStack:["Angular","NestJS (Node.js)","PostgreSQL","Redis"]}]}},{type:"c4-diagram",data:{imageSrc:"https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80",imageAlt:"Sch\xE9ma Architecture Syst\xE8me C4 Niveau 1 Liko Auto",caption:"Diagramme de contexte C4 (Niveau 1) : Flux de donn\xE9es et interconnexion des briques applicatives Liko Auto"}},{type:"process",data:{id:"process",title:"Comment Nous Avons Travaill\xE9 Ensemble",introText:"Pour transformer une id\xE9e ambitieuse en un produit scalable et s\xE9curis\xE9, l\u2019\xE9quipe d\u2019Evolia Tech a orchestr\xE9 un accompagnement 360\xB0 sur 5 mois. Nous avons structur\xE9 le projet en 5 phases cl\xE9s, garantissant une clart\xE9 totale et un contr\xF4le permanent pour les fondateurs.",steps:[{number:1,title:"Recueil des Besoins M\xE9tier, Cadrage & Maquettes UX/UI (Figma)",duration:"3 semaines",description:"Ateliers d\u2019immersion avec les fondateurs pour cartographier le parcours de chaque utilisateur (acheteurs, vendeurs, garages agr\xE9\xE9s, mod\xE9rateurs). Conception de maquettes interactives sur-mesure sur Figma, valid\xE9es \xE9cran par \xE9cran avant la moindre ligne de code."},{number:2,title:"Architecture Backend, Base de Donn\xE9es & APIs S\xE9curis\xE9es",duration:"5 semaines",description:'Construction du "moteur central" de la plateforme : mod\xE9lisation de la base de donn\xE9es, cr\xE9ation des serveurs haute performance (NestJS), s\xE9curisation de la messagerie instantan\xE9e et mise en place des r\xE8gles d\u2019acc\xE8s administrateur.'},{number:3,title:"D\xE9veloppement de l\u2019Application Mobile & des Portails Web",duration:"7 semaines",description:"D\xE9veloppement de l\u2019application mobile cross-platform (iOS & Android sur Flutter), de la vitrine web optimis\xE9e pour le r\xE9f\xE9rencement Google (Angular SSR) et du dashboard d\u2019administration permettant de mod\xE9rer les annonces et piloter les stocks."},{number:4,title:"Tests de Charge, S\xE9curit\xE9 & Publication sur les Stores (Apple & Google)",duration:"3 semaines",description:"Tests d\u2019effort en conditions r\xE9elles de trafic, v\xE9rification de la confidentialit\xE9 des \xE9changes et gestion compl\xE8te des d\xE9marches administratives pour la publication officielle sur l\u2019App Store Apple et le Google Play Store."},{number:5,title:"Formation des \xC9quipes, Manuel d\u2019Utilisation & Tutoriels Vid\xE9o",duration:"2 semaines",description:"R\xE9daction du guide d\u2019utilisation complet, r\xE9alisation de tutoriels vid\xE9o p\xE9dagogiques pour l\u2019administration du site, et formation en direct des \xE9quipes op\xE9rationnelles de Liko Auto pour garantir une prise en main fluide et autonome."}],totalDuration:"5 mois"}},{type:"text",data:{id:"retrospective",title:"R\xE9trospective : Ce Que Nous Aurions Pu Am\xE9liorer",paragraphs:["Toute aventure num\xE9rique d'envergure est porteuse d'enseignements. Si la qualit\xE9 finale de Liko Auto est au rendez-vous, l'analyse r\xE9trospective de notre collaboration met en lumi\xE8re deux points majeurs que nous aurions pu mieux optimiser :"],listItems:["<strong>Privil\xE9gier les livraisons it\xE9ratives par modules plut\xF4t qu'un lancement global</strong> : En cherchant \xE0 livrer l'int\xE9gralit\xE9 de l'\xE9cosyst\xE8me en une seule fois (App mobile, Web SEO, Pi\xE8ces d\xE9tach\xE9es et Back-office), nous avons retard\xE9 l'acc\xE8s initial au march\xE9. D\xE9ployer la plateforme brique par brique aurait permis de r\xE9colter les retours utilisateurs plus t\xF4t.","<strong>Anticiper les d\xE9lais de validation externe des Stores (Apple & Google)</strong> : La proc\xE9dure de validation des applications mobiles par l'App Store et le Google Play Store a exig\xE9 des ajustements impr\xE9vus sur la politique de confidentialit\xE9, ajoutant des d\xE9lais de soumission ind\xE9pendants du d\xE9veloppement pur."]}},{type:"text",data:{id:"conclusion",title:"Conclusion : Une Vision R\xE9volutionnaire & Un Partenariat Durable",paragraphs:["Concevoir Liko Auto a \xE9t\xE9 une <strong>exp\xE9rience humaine et technique d'une qualit\xE9 exceptionnelle</strong> pour l'\xE9quipe d'Evolia Tech. B\xE2tir une solution capable de r\xE9inventer la confiance dans le march\xE9 automobile en Afrique Centrale est pr\xE9cis\xE9ment le type de d\xE9fi ambitieux qui anime notre agence.","Ce projet incarne notre vision du m\xE9tier : nous ne sommes pas de simples ex\xE9cutants de code, mais de <strong>v\xE9ritables partenaires technologiques de long terme</strong>. C'est pourquoi la mise en ligne n'\xE9tait qu'un d\xE9but : nous continuons d'accompagner quotidiennement Liko Auto dans la maintenance \xE9volutive, l'optimisation des performances et le d\xE9ploiement des nouvelles fonctionnalit\xE9s de la feuille de route."]}},{type:"gallery",data:{id:"gallery",title:"Galerie & Coulisses du Projet",introText:"Moments forts de notre collaboration, ateliers de travail en \xE9quipe, sessions de code intensives et aper\xE7u des interfaces cl\xE9s de la plateforme.",images:[{src:"https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80",alt:"Session de travail en \xE9quipe et ateliers de conception",caption:"Ateliers de cadrage UX/UI & brainstorming avec les fondateurs",aspectRatio:"wide"},{src:"https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=1200&q=80",alt:"Maquettage et wireframing d\u2019interfaces",caption:"Conception des maquettes interactives sur Figma",aspectRatio:"tall"},{src:"https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1200&q=80",alt:"Session de d\xE9veloppement et de code",caption:"D\xE9veloppement de l\u2019architecture backend NestJS & APIs s\xE9curis\xE9es",aspectRatio:"square"},{src:"https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=1200&q=80",alt:"Supercar sportive dans le showroom",caption:"Interface finale du catalogue de v\xE9hicules v\xE9rifi\xE9s",aspectRatio:"tall"},{src:"https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=80",alt:"Session de formation des \xE9quipes",caption:"C\xE9l\xE9bration du lancement en production & formation des op\xE9rateurs",aspectRatio:"wide"},{src:"https://images.unsplash.com/photo-1542282088-72c9c27ed0cd?auto=format&fit=crop&w=1200&q=80",alt:"Cockpit et affichage digital automobile",caption:"Tableau de bord administrateur & suivi des transactions en temps r\xE9el",aspectRatio:"square"}]}},{type:"cta",data:{id:"cta",title:"Vous avez une id\xE9e ambitieuse qui n\xE9cessite un partenaire technique engag\xE9 ?",description:"Parlons de votre projet, de vos d\xE9fis m\xE9tiers et d\xE9couvrons ensemble comment transformer votre vision en une plateforme puissante, p\xE9renne et rentable.",buttonText:"Concr\xE9tiser mon projet avec Evolia Tech",buttonLink:"/contact"}}],seoTitle:"Liko Auto | Marketplace Automobile Cameroun \u2014 Achat, Vente & Services Auto",seoDescription:"Liko Auto est la premi\xE8re marketplace automobile connect\xE9e du Cameroun : achat et vente de v\xE9hicules, messagerie instantan\xE9e, garages partenaires, pi\xE8ces d\xE9tach\xE9es et accompagnement aux d\xE9marches administratives.",keywords:"marketplace automobile Cameroun, acheter voiture Cameroun, vendre voiture Douala Yaound\xE9, Liko Auto, garage Cameroun, pi\xE8ces d\xE9tach\xE9es auto Afrique",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:11,order:2,slug:"association-mahol-diaspora",title:"Solidarit\xE9 & r\xE9seau professionnel de la diaspora",clientName:"Mahol Diaspora",showcaseImage:"/images/projects/mahol/mahol-diaspora.webp",isSpotlighted:!0,liveUrl:"https://www.maholdiaspora.com/",keyResults:[{value:"288+",label:"Adh\xE9rents actifs enregistr\xE9s"},{icon:"faUserTie",label:"Annuaire des professionnels"},{icon:"faHandHoldingHeart",label:"Collectes & Secours automatis\xE9s"},{icon:"faCogs",label:"Dashboard multi-d\xE9l\xE9gu\xE9s"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Contexte & Ambition"},{id:"challenges",label:"Les Enjeux"},{id:"approach",label:"Notre Approche"},{id:"solution",label:"La Solution"},{id:"c4-diagram",label:"Architecture"},{id:"process",label:"Le Processus"},{id:"retrospective",label:"R\xE9trospective"},{id:"conclusion",label:"Conclusion"},{id:"gallery",label:"Galerie"}],blocks:[{type:"overview",data:{title:'Plateforme sur-mesure de <span class="highlight">solidarit\xE9 internationale & r\xE9seau pro</span> de la diaspora',impactStatement:"Digitalisation compl\xE8te des adh\xE9sions, cotisations solidaires, fonds de secours d\u2019urgence et gestion des d\xE9l\xE9gu\xE9s, doubl\xE9e d\u2019un annuaire dynamique des professionnels pour stimuler le r\xE9seau et l\u2019entraide au sein de la diaspora camerounaise."}},{type:"media",data:{images:[{src:"/images/projects/mahol/mockup-mahol-diaspora.webp",alt:"Mahol Diaspora Plateforme Solidaire & Annuaire Pro",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Contexte & Ambition du Projet",paragraphs:["<strong>Mahol Diaspora</strong> est une association \xE0 but non lucratif d\xE9di\xE9e \xE0 l\u2019entraide, au secours d\u2019urgence et au d\xE9veloppement des Camerounais de la diaspora en France et \xE0 l\u2019international. Avant l\u2019intervention d\u2019Evolia Tech, la gestion de l\u2019association reposait sur des processus manuels (fichiers Excel, \xE9changes t\xE9l\xE9phoniques, appels \xE0 cotisations informels).","Face \xE0 l\u2019augmentation du nombre d\u2019adh\xE9rents et \xE0 la complexit\xE9 des r\xE8gles de solidarit\xE9 (secours en cas de d\xE9c\xE8s, accompagnement lors de mariages, fonds de soutien aux projets familiaux), les fondateurs avaient besoin d\u2019une plateforme centralis\xE9e, s\xE9curis\xE9e et p\xE9renne.","Au-del\xE0 du volet social, l\u2019ambition majeure de Mahol Diaspora \xE9tait de valoriser la richesse professionnelle de ses membres en cr\xE9ant un <strong>annuaire dynamique des professionnels et entrepreneurs de la diaspora</strong>, facilitant le mentorat, les opportunit\xE9s d\u2019affaires et la mise en r\xE9seau."]}},{type:"challenges",data:{id:"challenges",title:"Les Vrais Enjeux du Projet",challenges:["Automatiser et fiabiliser la gestion des adh\xE9sions, du renouvellement et du suivi comptable des cotisations.","Mod\xE9liser des r\xE8gles m\xE9tier complexes d\u2019attribution des fonds de secours et d\u2019entraide sociale (d\xE9c\xE8s, mariages, \xE9v\xE9nements de vie).","Instaurer un syst\xE8me d\u2019habilitations hi\xE9rarchis\xE9 par r\xF4les (RBAC) pour les D\xE9l\xE9gu\xE9s r\xE9gionaux, tr\xE9soriers et administrateurs.","Concevoir un annuaire interactif des professionnels de la diaspora avec filtres avanc\xE9s par m\xE9tiers, secteurs et zones g\xE9ographiques.","Offrir une interface intuitive et accessible sur mobile pour des membres de tous \xE2ges et de diverses ma\xEEtrises du num\xE9rique."]}},{type:"text",data:{id:"approach",title:"Notre Approche & M\xE9thodologie",paragraphs:["Pour r\xE9pondre aux exigences de transparence et de s\xE9curit\xE9 indispensables \xE0 une organisation associative solidaire, <strong>Evolia Tech a con\xE7u une architecture sur-mesure sous Angular et Node.js</strong>.","Nous avons travaill\xE9 main dans la main avec le bureau ex\xE9cutif de l\u2019association lors d\u2019ateliers UX/UI r\xE9guliers. Chaque \xE9cran du dashboard administrateur et de l\u2019espace membre a \xE9t\xE9 pens\xE9 pour r\xE9duire la charge mentale des d\xE9l\xE9gu\xE9s et garantir une tra\xE7abilit\xE9 totale des flux financiers et des dossiers de secours."]}},{type:"solution",data:{id:"solution",title:"La Solution 360\xB0 Mahol Diaspora",introText:"Un \xE9cosyst\xE8me digital complet interconnectant un portail grand public, un espace membre priv\xE9 et un dashboard de gestion m\xE9tier sur-mesure :",solutions:[{title:"1. Portail Web Public & Espace Membres",subtitle:"Pour les adh\xE9rents & la communaut\xE9",features:["Formulaire d\u2019adh\xE9sion en ligne fluide avec t\xE9l\xE9versement s\xE9curis\xE9 des justificatifs","Espace personnel permettant le suivi des cotisations, attestations et historiques de soutien","Consultation des actualit\xE9s de l\u2019association, des \xE9v\xE9nements solidaires et assembl\xE9es g\xE9n\xE9rales"],techStack:["Angular","TypeScript","SCSS","PrimeNG"]},{title:"2. Annuaire des Professionnels de la Diaspora",subtitle:"Pour le r\xE9seau, le mentorat & les affaires",features:["Recherche et filtres avanc\xE9s par m\xE9tiers (sant\xE9, ing\xE9nierie, droit, entrepreneuriat, artisanat, etc.)","Fiches profils d\xE9taill\xE9es favorisant la mise en relation directe entre professionnels de la diaspora","Module de recommandation et de r\xE9seautage pour stimuler la synergie \xE9conomique et l\u2019entraide pro"],techStack:["Angular","Search Engine","RBAC Security"]},{title:"3. Dashboard Administrateur & Pilotage M\xE9tier",subtitle:"Pour le bureau ex\xE9cutif & les d\xE9l\xE9gu\xE9s",features:["Gestion hi\xE9rarchis\xE9e des r\xF4les (Pr\xE9sidents, Tr\xE9soriers, D\xE9l\xE9gu\xE9s r\xE9gionaux et mod\xE9rateurs)","Suivi en temps r\xE9el des collectes, appels de cotisations automatis\xE9s et g\xE9n\xE9ration de bilans comptables","Module de validation et d\u2019instruction des dossiers de secours d\u2019urgence et prestations sociales"],techStack:["Node.js (Express)","PostgreSQL","JWT Auth","Nginx"]}]}},{type:"c4-diagram",data:{imageSrc:"https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1200&q=80",imageAlt:"Architecture Syst\xE8me Mahol Diaspora",caption:"Diagramme d\u2019architecture syst\xE8me C4 (Niveau 1) : Flux de cotisations solidaires, droits d\xE9l\xE9gu\xE9s et annuaire professionnel"}},{type:"process",data:{id:"process",title:"Comment Nous Avons Travaill\xE9 Ensemble",introText:"Un accompagnement 360\xB0 sur 4 mois pour transformer la gestion associative et booster le r\xE9seau pro :",steps:[{number:1,title:"Recueil des Besoins M\xE9tier & Mod\xE9lisation",duration:"3 semaines",description:"Cartographie d\xE9taill\xE9e des r\xE8gles de secours, r\xF4les des d\xE9l\xE9gu\xE9s et attentes du r\xE9seau professionnel. Maquettage Figma valid\xE9 \xE9cran par \xE9cran avec le bureau."},{number:2,title:"Architecture Backend, Base de Donn\xE9es & S\xE9curit\xE9",duration:"4 semaines",description:"Mod\xE9lisation de la base de donn\xE9es relationnelle, s\xE9curisation des donn\xE9es d\u2019adh\xE9rents (RGPD) et d\xE9veloppement des APIs REST."},{number:3,title:"D\xE9veloppement de l\u2019Espace Membre, Annuaire Pro & Back-Office",duration:"6 semaines",description:"D\xE9veloppement du portail public Angular, de l\u2019annuaire des professionnels avec filtres et du dashboard de gestion des cotisations."},{number:4,title:"Recette, Tests d\u2019Usabilit\xE9 & Formation des D\xE9l\xE9gu\xE9s",duration:"3 semaines",description:"Tests intensifs des flux de souscription, r\xE9daction des guides d\u2019utilisation et formation en direct des d\xE9l\xE9gu\xE9s r\xE9gionaux."}],totalDuration:"4 mois"}},{type:"text",data:{id:"retrospective",title:"R\xE9trospective : Ce Que Nous Aurions Pu Am\xE9liorer",paragraphs:["Chaque projet offre de pr\xE9cieuses le\xE7ons. L\u2019analyse r\xE9trospective de notre collaboration avec Mahol Diaspora met en avant deux points d\u2019am\xE9lioration :"],listItems:["<strong>Concevoir un syst\xE8me de rappels automatiques SMS en plus des e-mails</strong> : Une partie de la communaut\xE9 consulte plus facilement ses SMS ou messages WhatsApp que ses e-mails. L\u2019ajout de relances WhatsApp automatis\xE9es aurait encore acc\xE9l\xE9r\xE9 les renouvellements d\u2019adh\xE9sion.","<strong>Introduire des filtres par comp\xE9tences encore plus granulaires d\xE8s le lancement de l\u2019annuaire pro</strong> : Devant l\u2019engouement pour l\u2019annuaire des professionnels, les membres ont rapidement r\xE9clam\xE9 des sous-cat\xE9gories sp\xE9cifiques (ex: sp\xE9cialit\xE9s m\xE9dicales ou juridiques)."]}},{type:"text",data:{id:"conclusion",title:"Conclusion : Une Organisation Modernis\xE9e & Un R\xE9seau Fort",paragraphs:["Gr\xE2ce \xE0 cette plateforme sur-mesure, Mahol Diaspora dispose d\xE9sormais d\u2019un outil de gestion moderne, transparent et p\xE9renne qui renforce la confiance des adh\xE9rents.","L\u2019int\xE9gration de l\u2019annuaire des professionnels a permis de transformer une association d\u2019entraide sociale en une v\xE9ritable communaut\xE9 \xE9conomique et professionnelle dynamique."]}},{type:"gallery",data:{id:"gallery",title:"Galerie & Coulisses du Projet",introText:"Aper\xE7u des r\xE9unions de travail, sessions de conception UX et visuels de la plateforme.",images:[{src:"https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80",alt:"Session de travail en \xE9quipe",caption:"Ateliers de cadrage des r\xE8gles de secours & UX annuaire pro",aspectRatio:"wide"},{src:"https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=1200&q=80",alt:"Maquettage Figma",caption:"Conception des maquettes de l\u2019annuaire des professionnels",aspectRatio:"tall"},{src:"https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1200&q=80",alt:"D\xE9veloppement Backend",caption:"D\xE9veloppement de l\u2019architecture s\xE9curis\xE9e Node.js & PostgreSQL",aspectRatio:"square"},{src:"https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=80",alt:"Formation des d\xE9l\xE9gu\xE9s",caption:"Formation des d\xE9l\xE9gu\xE9s r\xE9gionaux \xE0 la prise en main du dashboard",aspectRatio:"wide"}]}},{type:"cta",data:{id:"cta",title:"Vous g\xE9rez une association, une mutuelle ou un r\xE9seau professionnel de la diaspora ?",description:"Digitalisez votre gestion de membres, vos collectes solidaires et cr\xE9ez votre annuaire professionnel sur-mesure avec Evolia Tech.",buttonText:"\xC9changer avec nos experts",buttonLink:"/contact"}}],seoTitle:"Mahol Diaspora | Plateforme Solidaire & Annuaire des Professionnels",seoDescription:"Portail web moderne pour l\u2019association Mahol Diaspora : gestion des membres, collectes solidaires et annuaire des professionnels de la diaspora.",keywords:"association solidaire, diaspora camerounaise, annuaire professionnels diaspora, Mahol Diaspora",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:1,order:3,slug:"for-you-media-africa",title:"Plateforme m\xE9dia digitale panafricaine moderne",clientName:"For You M\xE9dia Africa",showcaseImage:"/images/projects/for-you-media-afica/for-you-media.webp",isSpotlighted:!0,liveUrl:"https://foryoumediaafrica.com/",keyResults:[{icon:"faRocket",label:"Temps de chargement < 2s"},{icon:"faMobileAlt",label:"100% mobile-first"},{icon:"faChartLine",label:"SEO optimis\xE9"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Le Client & Contexte"},{id:"challenges",label:"Les D\xE9fis"},{id:"approach",label:"Notre Approche"},{id:"solution",label:"Notre Solution"},{id:"process",label:"Le Processus"},{id:"result-impact",label:"R\xE9sultats et Impact"},{id:"lessons-learned",label:"Le\xE7ons apprises"},{id:"conclusion",label:"Conclusion et CTA"}],blocks:[{type:"overview",data:{title:'Plateforme m\xE9dia digitale <span class="highlight">panafricaine moderne</span> & haut d\xE9bit',impactStatement:"Refonte compl\xE8te du site web de For You M\xE9dia Africa pour transformer une simple page de live en une v\xE9ritable plateforme m\xE9dia professionnelle, dynamique et immersive, digne des grands m\xE9dias internationaux."}},{type:"media",data:{images:[{src:"/images/projects/for-you-media-afica/mockup-foryou-media.webp",alt:"For You M\xE9dia Africa Plateforme",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Le Client & Contexte",paragraphs:["<strong>For You M\xE9dia Africa</strong> est une cha\xEEne de t\xE9l\xE9vision et radio panafricaine jeune et ambitieuse, diffusant des contenus d\u2019actualit\xE9, de divertissement et d\u2019information destin\xE9s \xE0 la jeunesse africaine.","Avant notre intervention, le site se limitait \xE0 une seule page statique affichant uniquement le live. Le promoteur souhaitait faire \xE9voluer la cha\xEEne vers un vrai m\xE9dia digital moderne capable de concurrencer les grands acteurs du secteur."]}},{type:"challenges",data:{id:"challenges",title:"Les D\xE9fis",challenges:["Passer d\u2019une simple page de live \xE0 une plateforme m\xE9dia compl\xE8te et professionnelle.","Cr\xE9er une exp\xE9rience utilisateur fluide et moderne inspir\xE9e des grands m\xE9dias internationaux.","D\xE9velopper une interface publique riche tout en cr\xE9ant un back-office complet pour g\xE9rer le contenu.","Permettre une mise \xE0 jour rapide du site selon l\u2019actualit\xE9 (hero banner dynamique).","Connecter le syst\xE8me avec YouTube pour g\xE9rer les replays via playlists.","Garantir une administration simple et s\xE9curis\xE9e avec diff\xE9rents niveaux de droits d\u2019acc\xE8s."]}},{type:"text",data:{id:"approach",title:"Notre Approche",paragraphs:["Nous avons pris l\u2019initiative de cette refonte en proposant une vision globale du projet. Apr\xE8s une analyse approfondie des meilleurs sites m\xE9dias internationaux, nous avons con\xE7u une solution sur-mesure alliant exp\xE9rience utilisateur premium et puissance de gestion.","L\u2019approche a \xE9t\xE9 it\xE9rative avec des validations r\xE9guli\xE8res pour garantir que le r\xE9sultat corresponde parfaitement \xE0 la vision et \xE0 l\u2019identit\xE9 de la cha\xEEne."]}},{type:"media",data:{src:"/images/projects/for-you-media.webp",alt:"Interface For You M\xE9dia"}},{type:"solution",data:{id:"solution",title:"Notre Solution",introText:"Une plateforme compl\xE8te alliant une interface publique immersive \xE0 un back-office intuitif permettant un pilotage autonome des contenus.",solutions:[{title:"1. Interface Publique M\xE9dia",subtitle:"Pour les t\xE9l\xE9spectateurs et auditeurs",features:["Live TV et Live Radio en direct","Replays des \xE9missions TV et Radio class\xE9s","Planning des \xE9missions sur 7 jours avec pr\xE9sentateurs et horaires","Hero banner dynamique modifiable selon l\u2019actualit\xE9"]},{title:"2. Espace d\u2019Administration",subtitle:"Pour l\u2019\xE9quipe r\xE9dactionnelle",features:["Gestion compl\xE8te des \xE9missions, pr\xE9sentateurs et cat\xE9gories","Gestion du programme TV et du planning hebdomadaire","Synchronisation automatique avec YouTube pour les replays","Syst\xE8me de mise \xE0 jour instantan\xE9e du Hero Banner"]}]}},{type:"process",data:{id:"process",title:"Le Processus",introText:"La r\xE9alisation du projet s\u2019est articul\xE9e autour de 4 phases cl\xE9s de conception et de lancement.",steps:[{number:1,title:"Cadrage, Analyse & Benchmark",description:"Ateliers avec l\u2019administration pour valider les r\xE8gles m\xE9tier, \xE9tude des meilleurs sites m\xE9dias internationaux et d\xE9finition des priorit\xE9s."},{number:2,title:"Conception Maquettes & UI/UX",description:"Maquettes d\xE9taill\xE9es de toutes les pages publiques et admin avec validation du promoteur."},{number:3,title:"D\xE9veloppement It\xE9ratif",description:"D\xE9veloppement Angular + Node.js avec int\xE9gration prioritaire du Live TV/Radio, du planning et de l\u2019administration."},{number:4,title:"Tests, Formation & Mise en Ligne",description:"Tests de charge complets, formation des \xE9quipes r\xE9dactionnelles et d\xE9ploiement final."}]}},{type:"impact",data:{id:"result-impact",title:"R\xE9sultats & Audience",introText:"Depuis son lancement, la plateforme web For You M\xE9dia Africa a d\xE9j\xE0 attir\xE9 plus de 9 400 utilisateurs et g\xE9n\xE9r\xE9 pr\xE8s de 23 000 sessions.",metrics:[{value:"~ 3 min",label:"Dur\xE9e moyenne par session"},{value:"+ 350",label:"Utilisateurs mensuels r\xE9guliers"},{value:"+ 9 400",label:"Utilisateurs uniques enregistr\xE9s"},{value:"+ 48 318",label:"Pages vues g\xE9n\xE9r\xE9es"}],imageSrc:"/images/projects/for-you-media-afica/ga-for-you-media.webp",imageAlt:"Audience Google Analytics For You M\xE9dia"}},{type:"highlight-cards",data:{cards:[{title:"Rayonnement g\xE9ographique & ancrage urbain",text:"Une audience fortement concentr\xE9e dans les grandes m\xE9tropoles d\u2019Afrique francophone et les principaux hubs de la diaspora, confirmant un ciblage pertinent et une adoption r\xE9elle dans les zones \xE0 fort potentiel m\xE9diatique.",imageSrc:"/images/projects/for-you-media-afica/ga-for-you-media-town.webp",imageAlt:"R\xE9partition g\xE9ographique audience",imagePosition:"left"},{title:"Strat\xE9gie device & r\xE9alit\xE9 d\u2019usage",text:"Pr\xE8s de 67,4 % de l\u2019audience consulte la plateforme sur mobile, confirmant les habitudes de consommation m\xE9dia en Afrique et en diaspora. Le desktop (31,3 %) reste essentiel pour les sessions longues. Cette r\xE9partition a dict\xE9 chaque choix UX mobile-first.",imageSrc:"/images/projects/for-you-media-afica/ga-for-you-media-devices.webp",imageAlt:"R\xE9partition par appareils",imagePosition:"right"}]}},{type:"text",data:{id:"lessons-learned",title:"Le\xE7ons Apprises",paragraphs:["L\u2019inspiration des grands m\xE9dias internationaux permet d\u2019atteindre rapidement un niveau de finition et d\u2019exigence \xE9lev\xE9.","La connexion avec YouTube pour les replays offre un gain de temps et une coh\xE9rence \xE9ditoriale majeures."],listItems:["Prendre l\u2019initiative de proposer une vision globale quand le client a un besoin \xE9mergent.","La flexibilit\xE9 (banner dynamique) est un pr\xE9requis indispensable pour la r\xE9activit\xE9 d\u2019un m\xE9dia."]}},{type:"text",data:{id:"conclusion",title:"Conclusion",paragraphs:["For You M\xE9dia Africa dispose d\xE9sormais d\u2019une plateforme digitale moderne, professionnelle et facile \xE0 g\xE9rer, capable d\u2019accompagner son d\xE9veloppement et son rayonnement panafricain.","Ce projet d\xE9montre notre capacit\xE9 \xE0 transformer une vision en une solution compl\xE8te, esth\xE9tique et fonctionnelle."]}},{type:"cta",data:{id:"cta",title:"Vous souhaitez moderniser votre pr\xE9sence digitale ou cr\xE9er une plateforme m\xE9dia ?",description:"D\xE9couvrez comment Evolia Tech peut vous accompagner dans le d\xE9veloppement de vos portails m\xE9dias et applications dynamiques.",buttonText:"\xC9changez avec nos experts",buttonLink:"/contact"}}],seoTitle:"For You M\xE9dia | Plateforme d\u2019Information et Divertissement Africaine",seoDescription:"D\xE9veloppement d\u2019une interface web dynamique et interactive pour For You M\xE9dia Africa.",keywords:"m\xE9dia africain, actualit\xE9 Afrique, For You M\xE9dia",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:4,order:4,slug:"soprano-vesinet",title:"Exp\xE9rience digitale immersive pour un restaurant gastronomique",clientName:"Soprano V\xE9sinet",showcaseImage:"/images/projects/soprano-vesinet/soprano-vesinet.webp",isSpotlighted:!0,liveUrl:"https://lesoprano.fr/",keyResults:[{icon:"faUtensils",label:"Menu interactif"},{icon:"faMagic",label:"Animations premium"},{icon:"faCalendarCheck",label:"R\xE9servation fluide"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Le Client & Contexte"},{id:"challenges",label:"Les D\xE9fis"},{id:"approach",label:"Notre Approche"},{id:"solution",label:"Notre Solution"},{id:"process",label:"Le Processus"},{id:"result-impact",label:"R\xE9sultats et Impact"},{id:"lessons-learned",label:"Le\xE7ons apprises"},{id:"conclusion",label:"Conclusion et CTA"}],blocks:[{type:"overview",data:{title:'<span class="highlight">Exp\xE9rience digitale immersive</span> pour un restaurant italien premium & festif',impactStatement:"Conception d\u2019un site vitrine \xE9l\xE9gant et performant pour Soprano V\xE9sinet, alliant identit\xE9 haut de gamme, r\xE9servation fluide via Zenchef et animations saisonni\xE8res, afin de renforcer l\u2019attractivit\xE9 et l\u2019exp\xE9rience client d\u2019un \xE9tablissement d\u2019exception."}},{type:"media",data:{images:[{src:"/images/projects/soprano-vesinet/mockup-soprano-vesinet.webp",alt:"Soprano V\xE9sinet Restaurant",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Le Client & Contexte",paragraphs:["<strong>Soprano V\xE9sinet</strong> est un restaurant italien premium du groupe SOPRANO GROUPE, situ\xE9 au V\xE9sinet (78). L\u2019\xE9tablissement se distingue par son positionnement haut de gamme, l\u2019accueil de personnalit\xE9s et l\u2019organisation de soir\xE9es th\xE9matiques avec DJ.","Initialement sollicit\xE9s pour digitaliser Amore Mio, nouvelle adresse du groupe, nous avons \xE9t\xE9 reconduits pour refondre la vitrine de l\u2019\xE9tablissement phare. La directive \xE9tait claire : concevoir une pr\xE9sence web \xE0 la hauteur d\u2019une r\xE9putation premium, capable de sublimer l\u2019ambiance festive tout en fluidifiant les r\xE9servations."]}},{type:"challenges",data:{id:"challenges",title:"Les D\xE9fis",challenges:["Traduire une identit\xE9 premium et festive en une exp\xE9rience web \xE9l\xE9gante et fluide.","Int\xE9grer le syst\xE8me de r\xE9servation Zenchef sans rompre l\u2019immersion visuelle.","Concevoir des animations d\u2019entr\xE9e contextuelles (No\xEBl, Halloween, \xE9v\xE9nements) sans impacter les performances.","Garantir un r\xE9f\xE9rencement local optimal et un chargement rapide gr\xE2ce au SSR Angular.","S\u2019aligner sur les standards du groupe SOPRANO tout en affirmant l\u2019identit\xE9 propre du V\xE9sinet."]}},{type:"text",data:{id:"approach",title:"Notre Approche",paragraphs:["Nous avons adopt\xE9 une d\xE9marche centr\xE9e sur l\u2019exp\xE9rience client et la performance technique. Apr\xE8s un \xE9change avec le community manager et la direction, nous avons d\xE9fini une identit\xE9 visuelle digitale coh\xE9rente avec l\u2019ambiance du lieu et les attentes d\u2019une client\xE8le exigeante.","Le d\xE9veloppement it\xE9ratif avec validations r\xE9guli\xE8res des animations et de l\u2019int\xE9gration Zenchef a garanti un rendu fluide et immersif."]}},{type:"media",data:{src:"/images/projects/soprano-vesinet.png",alt:"Visuel Soprano V\xE9sinet"}},{type:"solution",data:{id:"solution",title:"Notre Solution",introText:"Une plateforme vitrine pens\xE9e comme une extension digitale du restaurant, o\xF9 l\u2019\xE9l\xE9gance visuelle sert la conversion et la r\xE9servation.",solutions:[{title:"Exp\xE9rience Client & R\xE9servation",subtitle:"Design Premium & Zenchef",features:["Design d\u2019exception refl\xE9tant l\u2019ambiance festivo-gastronomique du lieu","Animations d\u2019entr\xE9e saisonni\xE8res et \xE9v\xE9nementielles sur-mesure","Pr\xE9sentation du menu, des soir\xE9es DJ du vendredi et des \xE9v\xE9nements","Parcours de r\xE9servation Zenchef accessible en 2 clics","Optimisation mobile-first fluide pour la client\xE8le en d\xE9placement"]}]}},{type:"process",data:{id:"process",title:"Le Processus",introText:"Un accompagnement sur-mesure en 4 \xE9tapes cl\xE9s sur 6 semaines.",steps:[{number:1,title:"Cadrage & Direction Artistique",duration:"1 semaine",description:"\xC9changes avec la direction, d\xE9finition de l\u2019identit\xE9 visuelle et du parcours de r\xE9servation."},{number:2,title:"Maquettes & Validation UX",duration:"1 semaine",description:"Conception des \xE9crans cl\xE9s, validation des animations saisonni\xE8res et du flux Zenchef."},{number:3,title:"D\xE9veloppement It\xE9ratif",duration:"3 semaines",description:"Int\xE9gration Angular SSR, animations contextuelles et connexion \xE0 l\u2019API Zenchef."},{number:4,title:"Tests, Optimisation & Lancement",duration:"1 semaine",description:"V\xE9rification des performances, tests cross-device et d\xE9ploiement."}],totalDuration:"6 semaines"}},{type:"impact",data:{id:"result-impact",title:"R\xE9sultats & Impact",introText:"Depuis sa mise en ligne, le site Soprano V\xE9sinet offre une vitrine digitale stable, rapide et align\xE9e sur le positionnement premium de l\u2019\xE9tablissement.",metrics:[{value:"100 %",label:"Rendu SSR instantan\xE9"},{value:"2 Clics",label:"R\xE9servation Zenchef fluide"}],imageSrc:"/images/projects/soprano-vesinet/ga-soprano-vesinet.png",imageAlt:"Performances Soprano V\xE9sinet"}},{type:"text",data:{id:"lessons-learned",title:"Le\xE7ons Apprises",paragraphs:["Les animations contextuelles renforcent l\u2019engagement mais doivent \xEAtre strictly optimis\xE9es pour ne pas p\xE9naliser la vitesse de chargement.","L\u2019int\xE9gration d\u2019un outil tiers (Zenchef) n\xE9cessite un travail fin sur l\u2019UX pour conserver une immersion visuelle fluide et \xE9l\xE9gante."]}},{type:"text",data:{id:"conclusion",title:"Conclusion",paragraphs:["Soprano V\xE9sinet dispose d\xE9sormais d\u2019une pr\xE9sence digitale \xE0 la hauteur de sa r\xE9putation : \xE9l\xE9gante, performante et pens\xE9e pour convertir les visiteurs en convives.","Ce projet illustre notre capacit\xE9 \xE0 allier direction artistique premium, int\xE9grations techniques fluides et performance web."]}},{type:"cta",data:{id:"cta",title:"Vous souhaitez cr\xE9er ou refondre le site de votre \xE9tablissement premium ?",description:"D\xE9couvrez comment Evolia Tech peut sublimer votre image et optimiser vos r\xE9servations en ligne.",buttonText:"\xC9changez avec nos experts",buttonLink:"/contact"}}],seoTitle:"Soprano V\xE9sinet | Restaurant Italien Haut de Gamme",seoDescription:"Conception d\u2019un site vitrine \xE9l\xE9gant pour le restaurant Soprano au V\xE9sinet.",keywords:"restaurant italien Le V\xE9sinet, Soprano V\xE9sinet",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:5,order:5,slug:"amore-mio",title:"Exp\xE9rience digitale festive & restaurant italien premium",clientName:"Amore Mio",image:"/images/projects/amore-mio.png",showcaseImage:"/images/projects/amore-mio/amore-mio.webp",isSpotlighted:!0,liveUrl:"https://amoremio78.com/",keyResults:[{icon:"faHeart",label:"Taux de conversion +35%"},{icon:"faMobileAlt",label:"UX Ultra-fluide"},{icon:"faRocket",label:"Temps de r\xE9ponse < 1.2s"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Contexte & Marque"},{id:"challenges",label:"Les D\xE9fis"},{id:"solution",label:"Notre Solution"},{id:"process",label:"Le Processus"},{id:"result-impact",label:"R\xE9sultats & Impact"},{id:"conclusion",label:"Conclusion"}],blocks:[{type:"overview",data:{title:'Exp\xE9rience digitale festive & <span class="highlight">gastronomie italienne</span> aux portes de Paris',impactStatement:"Conception et d\xE9veloppement d\u2019un site vitrine et plateforme d\u2019engagement sur-mesure pour Amore Mio, sublimant l\u2019ambiance chaleureuse et italienne du restaurant tout en fluidifiant la r\xE9servation et la visibilit\xE9 en ligne."}},{type:"media",data:{images:[{src:"/images/projects/amore-mio/mockup-amore-mio.webp",alt:"Amore Mio Restaurant Italien",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Le Client & Contexte",paragraphs:["<strong>Amore Mio</strong> est un \xE9tablissement italien chaleureux et \xE9l\xE9gant, inspir\xE9 des plus belles r\xE9gions d\u2019Italie et implant\xE9 aux portes de Paris (Le V\xE9sinet, 78). Il s\u2019impose comme une adresse culinaire et conviviale incontournable du groupe SOPRANO.","Alliant recettes traditionnelles, antipasti g\xE9n\xE9reux, pizzas napolitaines artisanales au feu de bois et cocktails cr\xE9atifs, le restaurant visait \xE0 transposer sur le web son atmosph\xE8re solaire, festive et gourmande.","Pour accompagner cette ambition, l\u2019\xE9quipe d\u2019Evolia Tech a con\xE7u une exp\xE9rience digitale immersive, rapide et mobile-first, pens\xE9e pour captiver les visiteurs et stimuler la r\xE9servation directe."]}},{type:"challenges",data:{id:"challenges",title:"Les D\xE9fis du Projet",challenges:["Refl\xE9ter fid\xE8lement l\u2019ambiance m\xE9diterran\xE9enne, moderne et festive du restaurant \xE0 travers une direction artistique \xE9l\xE9gante.","Optimiser le parcours de r\xE9servation et la consultation du menu interactif sur mobile (plus de 80% des visites).","Mettre en valeur la carte des plats, la s\xE9lection de cocktails et les \xE9v\xE9nements exclusifs (soir\xE9es DJ, brunchs d\u2019\xE9t\xE9).","Garantir une vitesse de chargement instantan\xE9e et un r\xE9f\xE9rencement local performant (SEO Google) pour Le V\xE9sinet et les Yvelines."]}},{type:"solution",data:{id:"solution",title:"Notre Solution 360\xB0",introText:"Une vitrine web haut de gamme pens\xE9e comme le prolongement digital de l\u2019exp\xE9rience en salle :",solutions:[{title:"1. Design Immersif & Direction Artistique",subtitle:"Identit\xE9 Italienne & \xC9l\xE9gance",features:["Direction artistique \xE9l\xE9gante associant typographies soign\xE9es et palettes douces inspir\xE9es de la Dolce Vita","Galeries visuelles immersives mettant en sc\xE8ne les plats signatures, la terrasse et la salle","Pr\xE9sentation claire et fluide des formules, cocktails et suggestions gourmandes"]},{title:"2. Parcours R\xE9servation & Performance Mobile",subtitle:"Conversion en 2 Clics & SEO Local",features:["Acc\xE8s instantan\xE9 au module de r\xE9servation en ligne optimis\xE9 pour smartphones","Architecture technique Angular SSR garantissant des temps de chargement sous les 1.2s","Optimisation pouss\xE9e du r\xE9f\xE9rencement local pour capter les recherches autour du V\xE9sinet et des Yvelines"]}]}},{type:"process",data:{id:"process",title:"Comment Nous Avons Travaill\xE9 Ensemble",introText:"Un accompagnement agile et structur\xE9 de la conception visuelle au d\xE9ploiement final :",steps:[{number:1,title:"Cadrage & Direction Artistique",duration:"1 semaine",description:"Immersion dans l\u2019univers de la marque, \xE9changes avec la direction et prototypage Figma des \xE9crans cl\xE9s."},{number:2,title:"D\xE9veloppement Angular SSR & Animations",duration:"3 semaines",description:"Int\xE9gration d\u2019une architecture web performante avec rendu serveur (SSR) et animations subtiles."},{number:3,title:"Int\xE9gration R\xE9servation & Menu Dynamic",duration:"1 semaine",description:"Configuration des flux de r\xE9servation et int\xE9gration du catalogue dynamique."},{number:4,title:"Optimisation SEO Local & Lancement",duration:"1 semaine",description:"Tests d\u2019ergonomie cross-device, audit de vitesse et mise en ligne officielle sur amoremio78.com."}],totalDuration:"6 semaines"}},{type:"impact",data:{id:"result-impact",title:"R\xE9sultats & Impact",introText:"Depuis le lancement de la plateforme web, Amore Mio b\xE9n\xE9ficie d\u2019une pr\xE9sence digitale forte, rapide et engageante.",metrics:[{value:"+35 %",label:"Taux de conversion r\xE9servations"},{value:"< 1.2s",label:"Temps de r\xE9ponse instantan\xE9"},{value:"82 %",label:"Trafic mobile optimis\xE9"},{value:"100 %",label:"Fluidit\xE9 & Ergonomie UX"}]}},{type:"cta",data:{id:"conclusion",title:"Vous souhaitez cr\xE9er ou refondre la vitrine digitale de votre \xE9tablissement ?",description:"D\xE9couvrez comment Evolia Tech transforme l\u2019exp\xE9rience visuelle de votre marque en un levier de r\xE9servation performant.",buttonText:"\xC9changer avec nos experts",buttonLink:"/contact"}}],seoTitle:"Amore Mio | Restaurant Italien au V\xE9sinet & Exp\xE9rience Digitale Premium",seoDescription:"D\xE9veloppement du site web du restaurant italien Amore Mio au V\xE9sinet : menu interactif, ambiance festive et r\xE9servation fluide.",keywords:"Amore Mio, restaurant italien Le V\xE9sinet, amoremio78, pizzeria Le V\xE9sinet, \xC9volia Tech",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:2,order:6,slug:"stella",title:"Boutique e-commerce headless premium",clientName:"Stella",showcaseImage:"/images/projects/stella.png",isSpotlighted:!0,keyResults:[{icon:"faShoppingCart",label:"Checkout ultra-rapide"},{icon:"faServer",label:"Architecture Headless"},{icon:"faShieldAlt",label:"Paiements s\xE9curis\xE9s"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Le Client & Contexte"},{id:"challenges",label:"Les D\xE9fis"},{id:"approach",label:"Notre Approche"},{id:"solution",label:"Notre Solution"},{id:"process",label:"Le Processus"},{id:"result-impact",label:"R\xE9sultats et Impact"},{id:"lessons-learned",label:"Le\xE7ons apprises"},{id:"conclusion",label:"Conclusion et CTA"}],blocks:[{type:"overview",data:{title:'Boutique e-commerce sur-mesure pour une <span class="highlight">marque de luxe</span> internationale',impactStatement:"Conception d\u2019une boutique en ligne enti\xE8rement ma\xEEtris\xE9e pour Stella, alliant architecture d\xE9coupl\xE9e (headless) pour une flexibilit\xE9 totale, parcours d\u2019achat premium et logistique internationale \xE9tendue."}},{type:"media",data:{src:"/images/projects/stella.png",alt:"Stella E-commerce Luxe"}},{type:"text",data:{id:"client-context",title:"Le Client & Contexte",paragraphs:["<strong>Stella</strong> est une marque de pr\xEAt-\xE0-porter de luxe destin\xE9e \xE0 une client\xE8le exigeante et \xE0 des personnalit\xE9s prestigieuses. Pr\xE9sente \xE0 l\u2019international, la marque commercialise des collections homme, femme et accessoires.","Souhaitant s\u2019affranchir des plateformes SaaS g\xE9n\xE9riques pour garder un contr\xF4le total sur son exp\xE9rience et ses flux, la direction nous a confi\xE9 la cr\xE9ation d\u2019un \xE9cosyst\xE8me e-commerce premium (architecture scalable, checkout ultra-fluide et gestion multi-devises)."]}},{type:"challenges",data:{id:"challenges",title:"Les D\xE9fis",challenges:["Livrer une architecture e-commerce robuste sous d\xE9lai contraint.","Int\xE9grer une logistique internationale complexe avec points relais dans des zones \xE0 acc\xE8s restreint.","Unifier les paiements (Stripe + Orange Money sur-mesure) et g\xE9rer la taxation multi-pays.","Concevoir un parcours d\u2019achat premium, rapide et s\xE9curis\xE9 pour une client\xE8le haut de gamme.","Mettre en place un dashboard administrateur avec gestion fine des r\xF4les et des variants produits."]}},{type:"text",data:{id:"approach",title:"Notre Approche",paragraphs:["Face \xE0 l\u2019urgence du planning, nous avons adopt\xE9 une approche de d\xE9veloppement direct structur\xE9e autour d\u2019une architecture headless, garantissant une base technique stable d\xE8s le premier jour.","Chaque flux critique (checkout, gestion des produits, paiements, logistique) a \xE9t\xE9 valid\xE9 en continu avec la cliente."]}},{type:"media",data:{src:"/images/projects/stella.png",alt:"Boutique Stella Interface"}},{type:"solution",data:{id:"solution",title:"Notre Solution",introText:"Un \xE9cosyst\xE8me e-commerce con\xE7u pour la scalabilit\xE9, le contr\xF4le m\xE9tier et l\u2019excellence op\xE9rationnelle.",solutions:[{title:"1. Exp\xE9rience Client & E-commerce",subtitle:"Parcours d\u2019achat & Paiements",features:["Catalogue premium (Homme/Femme/Accessoires) avec gestion des variants","Parcours de checkout fluide optimis\xE9 pour mobile et conversion","Paiements unifi\xE9s : Stripe + module Orange Money d\xE9velopp\xE9 sur-mesure","S\xE9lecteur de points relais pour les zones logistiques complexes"]},{title:"2. Espace d\u2019Administration & R\xF4les",subtitle:"Gestion m\xE9tier granulaire",features:["Dashboard sur-mesure : produits, collections, commandes et abonn\xE9s","Gestion des employ\xE9s avec attribution de r\xF4les et permissions fines","Configuration de la taxation multi-pays et des r\xE8gles de livraison"]},{title:"3. Architecture Headless & Performance",subtitle:"Angular SSR + Vendure.io",features:["Frontend Angular SSR : affichage instantan\xE9 et SEO optimal","Backend headless Vendure.io : catalogue et paiements d\xE9coupl\xE9s","D\xE9ploiement s\xE9curis\xE9 et scalable sur serveurs haute disponibilit\xE9"]}]}},{type:"process",data:{id:"process",title:"Le Processus",introText:"Une r\xE9alisation agile et intensive en 4 \xE9tapes cl\xE9s sur 4 semaines.",steps:[{number:1,title:"Cadrage Technique & Architecture",duration:"3 jours",description:"D\xE9finition de la stack headless, mod\xE9lisation des produits et flux de paiements."},{number:2,title:"D\xE9veloppement Direct & It\xE9rations",duration:"2 semaines",description:"Impl\xE9mentation Angular SSR + Vendure, catalogue et dashboard admin."},{number:3,title:"Int\xE9grations Critiques",duration:"1 semaine",description:"D\xE9veloppement du module Orange Money, points relais et taxation multi-pays."},{number:4,title:"Tests, D\xE9ploiement & Prise en Main",duration:"4 jours",description:"Tests de charge, v\xE9rification des paiements, d\xE9ploiement et formation."}],totalDuration:"4 semaines"}},{type:"impact",data:{id:"result-impact",title:"R\xE9sultats & Impact",introText:"L\u2019architecture est pleinement op\xE9rationnelle, pr\xEAte \xE0 absorber un trafic international et \xE0 scaler selon la croissance de la marque.",metrics:[{value:"Headless",label:"Architecture d\xE9coupl\xE9e & scalable"},{value:"Multi-Paiements",label:"Stripe + Orange Money natif"},{value:"SSR Activ\xE9",label:"Chargement instantan\xE9 & SEO"},{value:"Logistique",label:"Points relais internationaux"}],imageSrc:"/images/projects/stella/ga-stella.png",imageAlt:"Tableau de bord Stella Analytics"}},{type:"highlight-cards",data:{cards:[{title:"Rayonnement g\xE9ographique & couverture logistique",text:"Une architecture pens\xE9e pour le d\xE9ploiement mondial, avec une gestion native des zones \xE0 acc\xE8s restreint gr\xE2ce \xE0 un maillage de points relais sur-mesure.",imageSrc:"/images/projects/stella/ga-stella-geo.png",imageAlt:"Couverture g\xE9ographique Stella",imagePosition:"left"},{title:"Strat\xE9gie device & r\xE9alit\xE9 d\u2019usage",text:"Le parcours d\u2019achat a \xE9t\xE9 optimis\xE9 pour une consultation majoritairement mobile, tout en conservant un confort desktop premium. Le SSR Angular garantit un temps de chargement instantan\xE9, d\xE9cisif pour la conversion sur le segment luxe.",imageSrc:"/images/projects/stella/ga-stella-devices.png",imageAlt:"R\xE9partition des acc\xE8s par appareils",imagePosition:"right"}]}},{type:"text",data:{id:"lessons-learned",title:"Le\xE7ons Apprises",paragraphs:["L\u2019architecture d\xE9coupl\xE9e (headless) offre une flexibilit\xE9 in\xE9gal\xE9e pour int\xE9grer des paiements et une logistique complexe.","Cr\xE9er des modules sur-mesure (Orange Money, points relais) est un formidable levier de diff\xE9renciation pour les march\xE9s \xE9mergents."]}},{type:"text",data:{id:"conclusion",title:"Conclusion",paragraphs:["Stella dispose d\xE9sormais d\u2019une plateforme e-commerce sur-mesure, scalable et enti\xE8rement ma\xEEtris\xE9e, capable de supporter une croissance internationale sans compromis.","Ce projet d\xE9montre notre capacit\xE9 \xE0 livrer des architectures e-commerce robustes et des modules m\xE9tiers sur-mesure."]}},{type:"cta",data:{id:"cta",title:"Vous ambitionnez de lancer ou migrer votre boutique e-commerce ?",description:"Parlons de votre projet et concevons une solution performante adapt\xE9e \xE0 vos march\xE9s.",buttonText:"\xC9changez avec nos experts",buttonLink:"/contact"}}],seoTitle:"D\xE9veloppement E-commerce Stella | Expert Vendure & Angular",seoDescription:"D\xE9couvrez l\u2019architecture headless Vendure et le frontend Angular ultra-rapide.",keywords:"e-commerce Afrique, Vendure, NestJS",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:6,order:7,slug:"celebrate-congo",title:"Portail d\u2019engagement citoyen & c\xE9l\xE9bration nationale",clientName:"Celebrate Congo",showcaseImage:"/images/projects/celebrate-congo/celebrate-congo.webp",isSpotlighted:!0,keyResults:[{value:"50k+",label:"Cartes g\xE9n\xE9r\xE9es & engagements"},{icon:"faFlame",label:"Flamme virtuelle de l\u2019Unit\xE9"},{icon:"faGlobeAmericas",label:"Rayonnement diaspora mondial"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"client-context",label:"Contexte & Ambition"},{id:"challenges",label:"Les D\xE9fis Techniques"},{id:"solution",label:"La Plateforme"},{id:"process",label:"Le Processus"},{id:"result-impact",label:"Impact & Mobilisation"},{id:"retrospective",label:"R\xE9trospective"},{id:"conclusion",label:"Conclusion"}],blocks:[{type:"overview",data:{title:'Dispositif num\xE9rique d\u2019engagement & <span class="highlight">c\xE9l\xE9bration nationale</span> du Congo',impactStatement:"Conception et d\xE9veloppement d\u2019une plateforme web virale et interactive pour Celebrate Congo, permettant \xE0 la communaut\xE9 congolaise en patrie et dans la diaspora de c\xE9l\xE9brer la f\xEAte nationale du 15 Ao\xFBt, de g\xE9n\xE9rer des cartes personnalis\xE9es, d\u2019allumer la flamme de l\u2019unit\xE9 et de d\xE9couvrir les h\xE9ros de l\u2019histoire du Congo."}},{type:"media",data:{images:[{src:"/images/projects/celebrate-congo/mockup-celebrate-congo.webp",alt:"Celebrate Congo Plateforme",variant:"mockup"}]}},{type:"text",data:{id:"client-context",title:"Contexte & Ambition du Projet",paragraphs:["\xC0 l\u2019occasion de la <strong>66\xE8me c\xE9l\xE9bration nationale de la f\xEAte de l\u2019ind\xE9pendance du Congo (15 Ao\xFBt)</strong>, l\u2019initiative <strong>Celebrate Congo</strong> visait \xE0 cr\xE9er un \xE9lan d\u2019unit\xE9 num\xE9rique rassemblant la jeunesse, les citoyens \xE0 Brazzaville et Pointe-Noire, ainsi que toute la diaspora congolaise r\xE9pandue \xE0 travers le monde.","La plateforme portait une triple ambition : permettre \xE0 chaque Congolais d\u2019<strong>allumer symboliquement sa flamme pour le Congo</strong>, de <strong>personnaliser une carte officielle aux couleurs nationales \u{1F1E8}\u{1F1EC}</strong> et de la partager instantan\xE9ment sur WhatsApp, Instagram, Facebook et X (Twitter), transformant ainsi chaque participant en ambassadeur actif de la c\xE9l\xE9bration.","Pour aller au-del\xE0 du simple \xE9v\xE9nementiel num\xE9rique, la plateforme int\xE9grait \xE9galement une <strong>section Histoire & R\xE9v\xE9lation</strong> valorisant les h\xE9ros oubli\xE9s de l\u2019histoire du Congo \u2014 personnalit\xE9s embl\xE9matiques dont les r\xE9cits ont forg\xE9 l\u2019identit\xE9 nationale \u2014 ainsi qu\u2019un espace de soutien permettant aux sponsors et partenaires de s\u2019associer \xE0 cet \xE9lan patriotique."]}},{type:"challenges",data:{id:"challenges",title:"Les D\xE9fis Techniques & UX",challenges:["D\xE9velopper un g\xE9n\xE9rateur dynamique de cartes personnalis\xE9es haute d\xE9finition (Canvas HD) fonctionnant de fa\xE7on ultra-fluide sur tout type de smartphone, m\xEAme en zone \xE0 faible connectivit\xE9.","Absorber des pics de trafic massifs et simultan\xE9s le jour du 15 Ao\xFBt, sans aucun ralentissement ni indisponibilit\xE9 serveur.","Cr\xE9er une exp\xE9rience de partage direct optimis\xE9e pour WhatsApp, Instagram, Facebook et X (Twitter) avec des visuels au format adapt\xE9 \xE0 chaque r\xE9seau.","Mettre en place un compteur interactif en temps r\xE9el des flammes allum\xE9es, connect\xE9 \xE0 une base de donn\xE9es mise \xE0 jour instantan\xE9ment \xE0 chaque participation.","Concevoir et livrer un back-office complet pour que l\u2019\xE9quipe Celebrate Congo puisse g\xE9rer en totale autonomie les messages de participation, les histoires des h\xE9ros publi\xE9es en front-end, et la base de contacts de la newsletter.","Assurer la mod\xE9ration efficace des messages d\u2019unit\xE9 soumis par les participants avant leur affichage public, pour garantir un environnement sain et bienveillant."]}},{type:"solution",data:{id:"solution",title:"La Solution 360\xB0 Celebrate Congo",introText:"Un \xE9cosyst\xE8me digital complet en deux volets : une WebApp publique festive & engageante, et un back-office de pilotage \xE9ditorial sur-mesure :",solutions:[{title:"1. Interface Publique & Modules d\u2019Engagement",subtitle:"Pour toute la communaut\xE9 congolaise",features:["G\xE9n\xE9rateur de cartes personnalis\xE9es : upload de photo, saisie du nom et choix du message d\u2019unit\xE9 avec rendu Canvas HD instantan\xE9",'Module "J\u2019allume ma flamme" avec compteur temps r\xE9el des participants enregistr\xE9s depuis le Congo et la diaspora mondiale',"Partage en un clic vers WhatsApp, Instagram, Facebook et X avec visuels format\xE9s par r\xE9seau social","Section Histoire : galerie des figures historiques et h\xE9ros du pass\xE9 du Congo, enrichie dynamiquement depuis l\u2019administration","Section R\xE9v\xE9lation : contenu \xE9ditorial et messages forts autour de l\u2019identit\xE9 et de l\u2019unit\xE9 nationale congolaise","Espace Sponsors & Direct : mise en avant des partenaires et lien vers la diffusion en direct de la c\xE9l\xE9bration nationale","Newsletter : formulaire d\u2019inscription pour rester inform\xE9 des prochaines initiatives Celebrate Congo"],techStack:["Angular","Canvas API","TypeScript","SCSS","Node.js"]},{title:"2. Back-Office \xC9ditorial & Administration",subtitle:"Pour l\u2019\xE9quipe Celebrate Congo",features:["Tableau de bord de mod\xE9ration des messages d\u2019unit\xE9 : validation, rejet ou signalement des messages soumis par les participants avant publication publique","Gestion compl\xE8te des Histoires & H\xE9ros du Congo : cr\xE9ation, \xE9dition et publication depuis l\u2019admin avec affichage instantan\xE9 sur la page Histoire publique","Module de gestion de la newsletter : consultation de la base de contacts, export des abonn\xE9s et suivi des inscriptions","Interface s\xE9curis\xE9e par authentification JWT avec acc\xE8s restreint \xE0 l\u2019\xE9quipe \xE9ditoriale de Celebrate Congo"],techStack:["Angular","Node.js","PostgreSQL","JWT Auth"]}]}},{type:"process",data:{id:"process",title:"Le Processus de R\xE9alisation",introText:"Une ex\xE9cution agile et r\xE9active men\xE9e en 4 semaines, du cadrage au lancement officiel :",steps:[{number:1,title:"Cadrage, Direction Artistique & Maquettes UX/UI",duration:"1 semaine",description:"D\xE9finition de l\u2019identit\xE9 visuelle patriotique (couleurs nationales du Congo, typographies impactantes), conception des maquettes Figma pour toutes les pages publiques et le back-office, validation avec le client."},{number:2,title:"D\xE9veloppement du Moteur Canvas & Interface Publique",duration:"1.5 semaine",description:"Impl\xE9mentation Angular de l\u2019ensemble des modules publics : g\xE9n\xE9rateur de cartes Canvas HD, syst\xE8me de flamme avec compteur temps r\xE9el, pages Histoire, R\xE9v\xE9lation, Sponsors et formulaire newsletter."},{number:3,title:"D\xE9veloppement du Back-Office & APIs",duration:"1 semaine",description:"Construction du backend Node.js et des APIs REST s\xE9curis\xE9es : module de mod\xE9ration des messages, gestion CRUD des histoires des h\xE9ros, administration de la newsletter et syst\xE8me d\u2019authentification JWT."},{number:4,title:"Tests de Charge, Recette & Lancement Officiel",duration:"0.5 semaine",description:"Validation des performances sous trafic intense (simulation de milliers de participants simultan\xE9s), tests de la mod\xE9ration, v\xE9rification des flux de partage social et mise en ligne officielle le 15 Ao\xFBt."}],totalDuration:"4 semaines"}},{type:"impact",data:{id:"result-impact",title:"R\xE9sultats & Impact Communautaire",introText:"La plateforme Celebrate Congo a rencontr\xE9 un immense succ\xE8s populaire \xE0 travers le pays et au sein de la diaspora.",metrics:[{value:"50k+",label:"Cartes cr\xE9\xE9es & engagements"},{value:"100 %",label:"Disponibilit\xE9 sous pic de trafic"},{value:"< 1s",label:"G\xE9n\xE9ration instantan\xE9e du visuel"},{value:"30+",label:"Pays repr\xE9sent\xE9s dans la diaspora"}]}},{type:"cta",data:{id:"conclusion",title:"Vous souhaitez lancer une campagne d\u2019engagement citoyen ou un \xE9v\xE9nement digital viral ?",description:"D\xE9couvrez comment Evolia Tech con\xE7oit des WebApps interactives et g\xE9n\xE9rateurs de visuels \xE0 forte valeur virale.",buttonText:"Concr\xE9tiser votre projet avec nos experts",buttonLink:"/contact"}}],seoTitle:"Celebrate Congo | Portail d\u2019Engagement & Carte de C\xE9l\xE9bration Nationale",seoDescription:"D\xE9veloppement de la plateforme interactive Celebrate Congo : g\xE9n\xE9rateur de carte personnalis\xE9e, flamme de l\u2019unit\xE9 et c\xE9l\xE9bration de l\u2019ind\xE9pendance.",keywords:"Celebrate Congo, 15 ao\xFBt Congo, ind\xE9pendance du Congo, carte personnalis\xE9e Congo, \xC9volia Tech",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:7,order:8,slug:"presidentielles-cameroun",title:"Dispositif num\xE9rique d\u2019engagement citoyen & donn\xE9es \xE9lectorales",clientName:"Pr\xE9sidentielles Cameroun",image:"/images/projects/presidentielles-cameroun.png",isSpotlighted:!0,keyResults:[{value:"100k+",label:"Engagements citoyens"},{icon:"faUsers",label:"Cartographie interactive"},{icon:"faMobileAlt",label:"100% Responsive"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"contexte",label:"Contexte Citoyen"},{id:"defis",label:"D\xE9fis de Mobilisation"},{id:"solution",label:"Dispositif Num\xE9rique"},{id:"resultats",label:"Impact & Engagement"}],seoTitle:"Pr\xE9sidentielles Cameroun | Dispositif d\u2019Engagement Citoyen",seoDescription:"Plateforme interactive et cartographie dynamique d\u2019engagement pour les pr\xE9sidentielles au Cameroun.",keywords:"Pr\xE9sidentielles Cameroun, engagement citoyen, cartographie \xE9lectorale, \xC9volia Tech",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:8,order:9,slug:"presidentielles-senegal",title:"Plateforme d\u2019information & suivi en temps r\xE9el des \xE9lections",clientName:"Pr\xE9sidentielles S\xE9n\xE9gal",image:"/images/projects/presidentielles-senegal.png",isSpotlighted:!1,keyResults:[{value:"99.99%",label:"Disponibilit\xE9 serveur"},{icon:"faChartLine",label:"Data visualization live"},{icon:"faShieldAlt",label:"Haute s\xE9curit\xE9 & anti-DDoS"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"contexte",label:"Contexte \xC9lectoral"},{id:"defis",label:"D\xE9fis de Scalabilit\xE9"},{id:"solution",label:"Architecture & Dashboard"},{id:"resultats",label:"R\xE9sultats & S\xE9curit\xE9"}],seoTitle:"Pr\xE9sidentielles S\xE9n\xE9gal | Suivi \xC9lectoral & Visualisation de Donn\xE9es",seoDescription:"Plateforme hautement s\xE9curis\xE9e de suivi des r\xE9sultats et actualit\xE9s des \xE9lections pr\xE9sidentielles au S\xE9n\xE9gal.",keywords:"Pr\xE9sidentielles S\xE9n\xE9gal, donn\xE9es \xE9lectorales, haute disponibilit\xE9, \xC9volia Tech",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:9,order:10,slug:"parti-politique-purs",title:"Portail institutionnel & espace adh\xE9rents pour le P.U.R.S",clientName:"Parti Politique P.U.R.S",image:"/images/projects/purs.png",isSpotlighted:!1,keyResults:[{value:"+10k",label:"Adh\xE9rents enregistr\xE9s"},{icon:"faUserCheck",label:"Gestion des membres"},{icon:"faNewspaper",label:"Espace m\xE9dia & actu"}],sections:[{id:"overview",label:"Aper\xE7u"},{id:"contexte",label:"Vision & Engagement"},{id:"defis",label:"Gestion des Adh\xE9sions"},{id:"solution",label:"Portail & Espace Membre"},{id:"resultats",label:"Impact Communautaire"}],seoTitle:"Parti Politique P.U.R.S | Portail Institutionnel & Adh\xE9sions",seoDescription:"Conception du portail officiel et de l\u2019espace adh\xE9rents s\xE9curis\xE9 du parti politique P.U.R.S.",keywords:"P.U.R.S, parti politique, portail membre, \xC9volia Tech",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"},{id:10,order:11,slug:"elites-voyages",title:"Voyage de luxe sur-mesure",clientName:"Elites Voyages",image:"/images/projects/elites-voyages.png",isSpotlighted:!1,keyResults:[{icon:"faGlobeAmericas",label:"Destinations infinies"},{icon:"faCameraRetro",label:"Galeries immersives"},{icon:"faMapMarkedAlt",label:"Cartographie interactive"}],sections:[{id:"concept",label:"La Vision"},{id:"destinations",label:"Destinations"},{id:"interface",label:"Interface"}],seoTitle:"Elites Voyages | Agence de Voyage sur-mesure & S\xE9jours de Luxe",seoDescription:"Plateforme digitale con\xE7ue pour l\u2019exploration de destinations mondiales.",keywords:"voyage sur mesure, agence de voyage luxe",seoImage:"https://evolia-tech.com/images/logo-evolia-tech.png"}];export{f as a,P as b};
